/* Service worker: offline app shell. The precache list and cache name are generated by `npm run build`. */
importScripts("./precache.generated.js");

const CACHE_NAME = self.COVERDRAFT_CACHE;
const APP_SHELL = self.COVERDRAFT_PRECACHE;
const CDN_HOSTS = new Set([
  "cdnjs.cloudflare.com",
  "fonts.googleapis.com",
  "fonts.gstatic.com"
]);


self.addEventListener("install", (event) => {
  // Keep install responsive. Third-party scripts/styles are cached by the fetch
  // handler as the app loads them; offline editing never waits on a CDN timeout.
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    await cache.addAll(APP_SHELL);
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => key.startsWith("coverdraft-static-") && key !== CACHE_NAME)
      .map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin && !CDN_HOSTS.has(url.hostname)) return;

  if (request.mode === "navigate") {
    event.respondWith((async () => {
      try {
        const response = await fetch(request);
        if (response.ok) {
          const cache = await caches.open(CACHE_NAME);
          const cacheWrite = cache.put("./index.html", response.clone()).catch(() => { });
          try { event.waitUntil(cacheWrite); } catch (_) { /* Keep the online response usable if background caching is unavailable. */ }
        }
        return response;
      } catch {
        return (await caches.match("./index.html")) || (await caches.match("./"));
      }
    })());
    return;
  }

  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    const cached = await cache.match(request);
    if (cached) return cached;
    try {
      const response = await fetch(request);
      if (response && (response.ok || response.type === "opaque")) {
        const cacheWrite = cache.put(request, response.clone()).catch(() => { });
        try { event.waitUntil(cacheWrite); } catch (_) { /* The response remains valid even if caching cannot be extended. */ }
      }
      return response;
    } catch (error) {
      if (cached) return cached;
      throw error;
    }
  })());
});
